sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
(function executeRule(current, gForm, gSNC) {
    var equipType = gForm.getValue('equipment_type');

    if (equipType === 'Hardware') {
        gForm.clearValue('software_item'); // Clear software field if switching
        window.location.href = '/sp?id=sc_category&sys_id=YOUR_HARDWARE_CATEGORY_SYSID';
    } else if (equipType === 'Software') {
        gForm.clearValue('hardware_item'); // Clear hardware field if switching
        window.location.href = '/sp?id=sc_category&sys_id=YOUR_SOFTWARE_CATEGORY_SYSID';
    }
})(current, gForm, gSNC);







    //Type appropriate comment here, and begin script below

}
